import { expect, type Page } from "@playwright/test";

export const getLocators = (page: Page) => ({
  viewCodeButton: page.getByRole("button", { name: "Click to view code" }),
  dialog: page.getByRole("dialog"),
  dialogCloseButton: page.getByRole("button", { name: "Cancel" }),
});

export const actions = (page: Page) => {
  const locators = getLocators(page);

  return {
    openCustomJsonModal: async () => {
      await expect(
        locators.viewCodeButton,
        "Click to view code button should be visible",
      ).toBeVisible();
      await locators.viewCodeButton.click();
    },
    closeCustomJsonModal: async () => {
      await locators.dialogCloseButton.click();
    },
  };
};

export const assertions = (page: Page) => {
  const locators = getLocators(page);

  return {
    customJsonDialogIsVisible: async () => {
      await expect(locators.dialog, "Custom JSON dialog should be visible").toBeVisible();
    },
    customJsonDialogContains: async (text: string) => {
      await expect(locators.dialog, `Custom JSON dialog should contain "${text}"`).toContainText(
        text,
      );
    },
    customJsonDialogIsHidden: async () => {
      await expect(locators.dialog, "Custom JSON dialog should be hidden").toBeHidden();
    },
  };
};
